DB_PATH = os.environ.get('MY_AUDIT_DB', '/tmp/my_audit_standalone.db')

# Hard cap on request body size to prevent memory-exhaustion DoS (default 100 MB).
MAX_UPLOAD_BYTES = int(os.environ.get('MY_AUDIT_MAX_UPLOAD', str(100 * 1024 * 1024)))

# Optional HTTP Basic Auth. Enabled only when BOTH env vars are set; the platform
# must never be exposed publicly without it. /health stays open for load balancers.
AUTH_USER = os.environ.get('MY_AUDIT_USER', '')
AUTH_PASS = os.environ.get('MY_AUDIT_PASS', '')
AUTH_ENABLED = bool(AUTH_USER and AUTH_PASS)
AUTH_REALM = 'My Audit Platform'

DASHBOARD_HTML_B64 = b""""""

DASHBOARD_HTML = base64.b64decode(DASHBOARD_HTML_B64).decode('utf-8')

# ==============================================================================
# 1. قاعدة البيانات والتهيئة (Database & Schema - Clean State)
# ==============================================================================
def get_db_connection():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON;")
    return conn

